import {LANGS,STORE,keyOf,emptyWord,parseWords,parseGrammar,parseVerbs,parseActivity,parseBackup,mergeLatest,schedule,cardPool,retryState,needsRetry,dayKey,recordActivity,chartSeries,evaluate,grammarResult,shuffle,searchText} from './core.js';
import {TEXT} from './i18n.js';
import {icon} from './icons.js';
import {readingPages,readingLookup} from './reading.js';
import {createVerbCourse,verbQuestionIds} from './verbs.js';
const $=id=>document.getElementById(id),h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const APP_VERSION='2.5.0';
let updateState='idle',updateError=false,cardTimer,cardRoute='cards';
const names={en:'English',uk:'Українська',tr:'Türkçe',ar:'العربية',ru:'Русский',fa:'فارسی',es:'Español'};
let catalog,keys,questionIds,vocabulary=null,grammar=null,wordMap=new Map(),questionMap=new Map(),vocabPromise,grammarPromise,reading=null,readingPromise;
let words={},results={},verbResults={},verbIds=new Set(),settings={lang:'en',theme:'light'},activity,storageOK=true,routeToken=0,toastTimer,offlineReady=false,offlineFailed=false,installPrompt=null,registration=null;
const ui={readingListPage:0,readingTopic:'all',readingLevel:'all',readingPositions:{},readingWord:null,topicPage:0,wordTopic:'all',filter:'all',query:'',limit:24,grammarPage:0,chartDays:7,chartMetric:'learned',open:new Set(),cardTopic:'all',deck:'due',direction:'de',card:null,gs:null};
const t=key=>TEXT[key]?.[LANGS.indexOf(settings.lang)]||key;
const status=w=>words[keyOf(w)]||emptyWord();
const learned=()=>Object.values(words).filter(r=>r.known).length;
const due=()=>Object.values(words).filter(r=>r.due>0&&r.due<=Date.now()).length;
const grammarStats=()=>{const r=Object.values(results),attempts=r.reduce((n,x)=>n+x.attempts,0);return {known:r.filter(x=>x.lastCorrect).length,attempts,accuracy:attempts?Math.round(r.reduce((n,x)=>n+x.correct,0)/attempts*100):0};};
const topicName=id=>catalog.topics.find(x=>x.id===id)?.de||t('allTopics');
const pct=(n,max)=>max?Math.round(n/max*100):0;
function read(key){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):null;}catch{storageOK=false;return null;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));}catch{storageOK=false;}showStorage();}
function showStorage(){const node=$('storageNotice');node.hidden=storageOK;node.textContent=t('blocked');}
const wordPayload=()=>({app:'Wortgarten',version:1,lang:settings.lang,progress:words});
const grammarPayload=()=>({app:'WortgartenGrammar',version:1,lang:settings.lang,records:results});
const verbPayload=()=>({app:'WortgartenVerbs',version:1,records:verbResults});
const verbCourse=createVerbCourse({fetchJSON,t,h,lang:()=>settings.lang,progress:()=>verbResults,save:(id,result)=>{verbResults[id]=result;write(STORE.verbs,verbPayload());record('grammar');},go,render,toast,element:$});
function record(event=null){activity=recordActivity(activity,learned(),event);write(STORE.activity,activity);}
function saveWord(w,changes,event=null){words[keyOf(w)]={...status(w),...changes,updated:Date.now()};write(STORE.words,wordPayload());record(event);}
function toast(key,isText=false){clearTimeout(toastTimer);$('toast').textContent=isText?key:t(key);$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4200);}
function loading(){return `<div class="loading"><span class="spinner"></span><p>${h(t('loading'))}</p></div>`;}
async function fetchJSON(file){const response=await fetch(new URL(file,import.meta.url));if(!response.ok)throw Error(response.status);return response.json();}
async function loadVocabulary(){if(vocabulary)return vocabulary;if(!vocabPromise)vocabPromise=fetchJSON('./content/vocabulary.json').then(data=>{vocabulary=data;wordMap=new Map(data.words.map(w=>[w.id,w]));for(const w of data.words)w.search=searchText([w.de,...LANGS.map(l=>w[l]),...(data.relations[w.de]||[])].join(' '));return data;}).catch(e=>{vocabPromise=null;throw e;});return vocabPromise;}
async function loadGrammar(){if(grammar)return grammar;if(!grammarPromise)grammarPromise=fetchJSON('./content/grammar.json').then(data=>{grammar=data;questionMap=new Map(data.flatMap(topic=>topic.questions.map(q=>[q.id,{...q,topic}])));return data;}).catch(e=>{grammarPromise=null;throw e;});return grammarPromise;}
async function loadReading(){if(reading)return reading;if(!readingPromise)readingPromise=fetchJSON('./content/reading.json').then(data=>{if(!Array.isArray(data.texts)||!data.glossary)throw Error('reading');reading=data;return data;}).catch(e=>{readingPromise=null;throw e;});return readingPromise;}
const route=()=>location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);
function go(path=''){location.hash='#/'+path;}
function backPath(p){if(p[0]==='verbs'&&p[1])return 'verbs';if(p[0]==='reading'&&p.length>1)return 'reading';if(p[0]==='words'&&p.length>1)return 'words';if(p[0]==='grammar'&&p[1]==='topics')return 'grammar';if(p[0]==='grammar'&&p[1]==='exercise')return ui.gs?.level?'grammar/topics/'+ui.gs.level:'grammar';return '';}
function applyTheme(){const dark=settings.theme==='dark'||settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]').content=dark?'#101c17':'#f4f6f2';}
function header(){const p=route(),dark=document.documentElement.dataset.theme==='dark';$('header').innerHTML=`<div class="headerStart">${p.length?`<button class="iconButton backButton" data-act="back" aria-label="${h(t('back'))}">${icon('back')}</button>`:''}<a class="brand ${p.length?'compactBrand':''}" href="#/" aria-label="Wortgarten"><span class="brandName">Wortgarten</span><span class="brandLeaf" aria-hidden="true">✳</span></a></div><div class="headerActions"><select class="languageQuick" id="quickLanguage" aria-label="${h(t('language'))}">${LANGS.map(l=>`<option value="${l}" ${l===settings.lang?'selected':''}>${names[l]}</option>`).join('')}</select><button class="iconButton" data-act="theme" aria-label="${h(t(dark?'light':'dark'))}" title="${h(t('appearance'))}">${icon(dark?'sun':'moon',19)}</button><button class="iconButton" data-go="settings" aria-label="${h(t('settings'))}">${icon('settings',19)}</button></div>`;
 const active=['reading','verbs'].includes(p[0])?'home':p[0]==='review'?'cards':p[0]||'home';$('navigation').innerHTML=[['','home','home'],['grammar','grammar','grammar'],['cards','cards','cards'],['words','book','words'],['progress','chart','progress']].map(([path,ic,label])=>`<a href="#/${path}" ${active===(path||'home')?'aria-current="page"':''}>${icon(ic)}<span>${h(t(label))}</span></a>`).join('');$('navigation').setAttribute('aria-label',t('home'));showStorage();}
function topicOptions(value){return `<option value="all">${h(t('allTopics'))}</option>`+catalog.topics.map(x=>`<option value="${x.id}" ${value===x.id?'selected':''}>${h(x.de)}</option>`).join('');}
function offlineLabel(){return t(offlineFailed?'offlineUnavailable':offlineReady?'availableOffline':'offlinePreparing');}
function homeHTML(){const pending=Object.values(words).filter(needsRetry),ready=pending.filter(r=>r.due<=Date.now()).length;const n=learned(),today=activity.days[dayKey()]||{reviews:0,grammar:0};return `<section class="screen homeScreen"><div class="homeGreeting"><h1>${h(t('hello'))}</h1><p class="subtitle">${h(t('welcome'))}</p></div><div class="homeStats"><div><strong>${n}<span style="font-size:14px;opacity:.65"> / ${catalog.uniqueWordCount}</span></strong><p class="small">${h(t('learnedWords'))}</p><div class="miniBar"><span style="width:${pct(n,catalog.uniqueWordCount)}%"></span></div></div><div style="flex:0 0 auto;text-align:end"><strong>${due()}</strong><p class="small">${h(t('due'))}</p></div></div><div class="homeGrid">${[['grammar','grammar','practiceGrammar','grammarSubtitle'],['cards','cards','cards','cardSubtitle'],['words','book','words','wordSubtitle'],['progress','chart','progress','progressSubtitle']].map(([path,ic,label,sub])=>`<button class="menuTile" data-go="${path}"><span class="tileIcon">${icon(ic)}</span><div><strong>${h(t(label))}</strong><p class="small">${h(sub==='grammarSubtitle'?grammarLevels().join('–')+' · '+catalog.grammarTopics.length+' '+t('topicsLabel'):t(sub))}</p></div></button>`).join('')}</div><div class="homeExtraGrid">${[['reading','book','reading','readingSubtitle'],['review','refresh','retryMenu','retryMenuHint'],['verbs','grammar','verbs','verbSubtitle']].map(([path,ic,label,sub])=>`<button class="menuTile" data-go="${path}"><span class="tileIcon">${icon(ic)}</span><div><strong>${h(t(label))}</strong><p class="small">${h(sub==='retryMenuHint'?t(sub).replace('{ready}',ready).replace('{total}',pending.length):t(sub))}</p></div></button>`).join('')}</div><div class="homeFoot"><span class="small">${h(t('today'))} · ${today.reviews+today.grammar} ${h(t('practiceCount'))}</span><span class="small"><span class="statusDot"></span>${h(offlineLabel())}</span></div></section>`;}

const readingKind=kind=>t({email:'readingEmail',dialogue:'readingDialogue',situation:'readingSituation'}[kind]);
function readingListHTML(){
 const texts=reading.texts.filter(text=>(ui.readingTopic==='all'||text.topic===ui.readingTopic)&&(ui.readingLevel==='all'||text.level===ui.readingLevel));
 const pages=Math.max(1,Math.ceil(texts.length/4));ui.readingListPage=Math.min(ui.readingListPage,pages-1);
 return `<section class="screen readingLibrary"><div><h1>${h(t('reading'))}</h1><p class="subtitle">${h(t('readingHint'))}</p></div><div class="filters"><select id="readingTopic" aria-label="${h(t('topic'))}">${topicOptions(ui.readingTopic)}</select><select id="readingLevel" aria-label="${h(t('readingLevel'))}">${['all','B1','B2'].map(level=>`<option value="${level}" ${ui.readingLevel===level?'selected':''}>${h(level==='all'?t('readingAllLevels'):level)}</option>`).join('')}</select></div><div class="readingTextList">${texts.slice(ui.readingListPage*4,ui.readingListPage*4+4).map(text=>`<button class="readingTextCard" data-go="reading/${text.id}"><span class="row between"><span class="pill">${h(text.level)} · ${h(readingKind(text.kind))}</span>${icon('arrow',16)}</span><strong lang="de" dir="ltr">${h(text.title)}</strong><span class="small" lang="de" dir="ltr">${h(topicName(text.topic))}</span></button>`).join('')||`<p class="small">${h(t('readingNoResults'))}</p>`}</div><div class="pager readingLibraryPager"><button class="secondary" data-act="reading-list-page" data-step="-1" ${ui.readingListPage===0?'disabled':''}>${h(t('previous'))}</button><span class="small" dir="ltr">${ui.readingListPage+1} / ${pages}</span><button class="secondary" data-act="reading-list-page" data-step="1" ${ui.readingListPage===pages-1?'disabled':''}>${h(t('next'))}</button></div></section>`;
}
function readingTextHTML(id){
 const text=reading.texts.find(text=>text.id===id);if(!text)return readingListHTML();
 const pages=readingPages(text),index=Math.min(ui.readingPositions[id]||0,pages.length-1);ui.readingPositions[id]=index;
 const body=pages[index].map(block=>`<div class="readingBlock">${block.speaker?`<span class="readingSpeaker" aria-label="${h(t('readingSpeaker'))} ${h(block.speaker)}">${h(block.speaker)}</span>`:''}<p>${block.tokens.map((token,i)=>token.glossId?`<button type="button" class="readingWord" data-act="reading-word" data-text="${id}" data-block="${block.blockIndex}" data-token="${block.start+i}" aria-haspopup="dialog">${h(token.text)}</button>`:h(token.text)).join('')}</p></div>`).join('');
 return `<section class="screen readingScreen"><div><div class="row between"><span class="pill">${h(text.level)} · ${h(readingKind(text.kind))}</span><span class="small" dir="ltr">${index+1} / ${pages.length}</span></div><h1 class="readingTitle" lang="de" dir="ltr">${h(text.title)}</h1><p class="small readingTapHint">${h(t('readingTap'))}</p></div><article class="readingPassage panel" lang="de" dir="ltr" aria-label="${h(text.title)}">${body}</article><div class="readingControls"><div class="pager"><button class="secondary" data-act="reading-page" data-text="${id}" data-step="-1" ${index===0?'disabled':''}>${h(t('previous'))}</button>${index<pages.length-1?`<button class="primary" data-act="reading-page" data-text="${id}" data-step="1">${h(t('next'))}</button>`:`<button class="primary" data-go="reading">${h(t('readingBack'))}</button>`}</div><button class="textButton" data-go="reading">${h(t('readingAllTexts'))}</button></div></section>`;
}
function readingGlossHTML(gloss){
 const star=gloss.wordId&&status({de:gloss.lemma}).star;
 return `<div class="readingGlossHeader"><span class="eyebrow">${h(t('readingMeaning'))}</span><button type="button" class="iconButton" data-act="reading-close" aria-label="${h(t('readingClose'))}" autofocus>${icon('close',18)}</button></div><h2 id="readingWordTitle" lang="de" dir="ltr">${h(gloss.surface)}</h2><p class="readingLemma" lang="de" dir="ltr">${h(gloss.lemma)}</p><p class="readingTranslation" lang="${settings.lang}" dir="${['ar','fa'].includes(settings.lang)?'rtl':'auto'}">${h(gloss[settings.lang])}</p><div class="readingGlossActions"><button class="secondary" data-act="reading-speak">${icon('sound',18)} ${h(t('speak'))}</button>${gloss.wordId?`<button class="secondary" data-act="reading-star" aria-pressed="${!!star}">${icon('star',18)} ${h(t(star?'unstar':'star'))}</button>`:''}</div>`;
}
function closeReadingWord(){ui.readingWord=null;if($('readingDialog').open)$('readingDialog').close();}
function showReadingWord(text,block,token){
 const gloss=readingLookup(reading,text,block,token);if(!gloss)return;
 ui.readingWord={text,block,token};$('readingWordContent').innerHTML=readingGlossHTML(gloss);$('readingDialog').showModal();
}

function topicsHTML(){const pages=Math.ceil(catalog.topics.length/6);ui.topicPage=Math.min(ui.topicPage,pages-1);return `<section class="screen"><div><h1>${h(t('chooseTopic'))}</h1><p class="subtitle">${h(t('wordSubtitle'))}</p></div><div class="topicsGrid">${catalog.topics.slice(ui.topicPage*6,ui.topicPage*6+6).map((topic,i)=>{const n=topic.keys.filter(k=>words[k]?.known).length;return `<button class="topicCard" data-go="words/${topic.id}"><div class="row"><span class="tileIcon">${icon(topic.icon||['briefcase','people','calendar','box','service','future'][ui.topicPage*6+i])}</span><span class="small">${topic.count}</span></div><span class="topicTitle" lang="de" dir="ltr">${h(topic.de)}</span><span class="small">${n} / ${topic.keys.length} · ${h(t('learned'))}</span><span class="topicBar"><span style="width:${pct(n,topic.keys.length)}%"></span></span></button>`;}).join('')}</div>${pages>1?`<div class="pager"><button class="secondary" data-act="topic-page" data-step="-1" ${ui.topicPage===0?'disabled':''}>${h(t('previous'))}</button><span class="small">${ui.topicPage+1}/${pages}</span><button class="secondary" data-act="topic-page" data-step="1" ${ui.topicPage===pages-1?'disabled':''}>${h(t('next'))}</button></div>`:''}<button class="secondary wide" data-go="words/all">${h(t('allWords'))} · ${catalog.wordCount}</button></section>`;}
function wordsHTML(topic){if(!catalog.topics.some(t=>t.id===topic)&&topic!=='all')return topicsHTML();if(ui.wordTopic!==topic){ui.wordTopic=topic;ui.query='';ui.filter='all';ui.limit=24;ui.open.clear();}return `<section class="screen"><div><h1 lang="${topic==='all'?settings.lang:'de'}" dir="${topic==='all'?'auto':'ltr'}">${h(topicName(topic))}</h1><div class="row between" style="margin-top:9px"><p class="small" id="wordCount"></p><button class="textButton" data-act="cards-topic" data-topic="${topic}">${h(t('cards'))} ${icon('arrow',14)}</button></div></div><div class="searchBox">${icon('search',19)}<input id="search" type="search" placeholder="${h(t('search'))}" aria-label="${h(t('search'))}" value="${h(ui.query)}" autocomplete="off"></div><div class="filters"><select id="wordFilter" aria-label="${h(t('filter'))}">${[['all','all'],['new','new'],['known','known'],['star','starred'],['verify','verifyFilter']].map(([value,label])=>`<option value="${value}" ${ui.filter===value?'selected':''}>${h(t(label))}</option>`).join('')}</select><select id="wordTopic" aria-label="${h(t('topic'))}">${topicOptions(topic)}</select></div><div class="wordList" id="wordList"></div><div id="moreWords"></div></section>`;}
function relationsHTML(w){const pair=vocabulary.relations[w.de];return pair?`<div class="relations">${pair.map((value,i)=>value?`<div><span>${h(t(i?'ant':'syn'))}</span><b lang="de" dir="ltr">${h(value)}</b></div>`:'').join('')}</div>`:'';}
function exampleHTML(w,scope){const id=scope+':'+w.id,open=ui.open.has(id);return `<details class="wordExample" data-example="${w.id}" data-scope="${scope}" ${open?'open':''}><summary>${h(t('example'))}</summary>${open?exampleBody(w):''}</details>`;}
function exampleBody(w){const ex=vocabulary.examples[w.exampleId];return `<div class="exampleBody"><p lang="de" dir="ltr">${h(ex.de)}</p><p lang="${settings.lang}" dir="${['ar','fa'].includes(settings.lang)?'rtl':'auto'}">${h(ex[settings.lang])}</p></div>`;}
function wordHTML(w){const s=status(w);return `<article class="word ${s.known?'known':''}" data-word="${w.id}"><div class="wordTop"><h2 lang="de" dir="ltr">${h(w.de)}</h2><button class="iconButton starButton" data-act="star" data-id="${w.id}" aria-label="${h(t(s.star?'unstar':'star'))}" aria-pressed="${s.star}">${icon('star',20)}</button></div><p class="wordTranslation" lang="${settings.lang}" dir="auto">${h(w[settings.lang])}</p>${relationsHTML(w)}${w.verify?`<p class="verify">${h(t('verify'))}</p>`:''}${exampleHTML(w,'word')}<div class="wordFooter"><button class="learnButton" data-act="learn" data-id="${w.id}" aria-pressed="${s.known}">${h(t(s.known?'unmark':'mark'))}</button><button class="iconButton" data-act="speak" data-id="${w.id}" aria-label="${h(t('speak'))}">${icon('sound',18)}</button></div></article>`;}
function renderWordList(){if(!$('wordList')||!vocabulary)return;const q=searchText(ui.query.trim()),list=vocabulary.words.filter(w=>{if(ui.wordTopic!=='all'&&w.topic!==ui.wordTopic)return false;const s=status(w);if(ui.filter==='new'&&s.known||ui.filter==='known'&&!s.known||ui.filter==='star'&&!s.star||ui.filter==='verify'&&!w.verify)return false;return !q||w.search.includes(q);});$('wordCount').textContent=`${Math.min(ui.limit,list.length)} / ${list.length} ${t('entries')}`;$('wordList').innerHTML=list.length?list.slice(0,ui.limit).map(wordHTML).join(''):`<div class="empty"><p>${h(t('noResults'))}</p></div>`;$('moreWords').innerHTML=list.length>ui.limit?`<button class="secondary wide" data-act="more">${h(t('loadMore'))}</button>`:'';}
function cardRetryState(){return vocabulary?retryState(vocabulary.words,words,{topic:ui.cardTopic,deck:ui.deck,skipped:ui.card?.skipped}):{ready:0,waiting:0,total:0,next:null};}
function retryCountdown(next){const seconds=Math.max(0,Math.ceil((next-Date.now())/1000));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function retryPanelHTML(q){return `<div class="retryPanel"><button class="retryDeckButton" data-act="retry-deck" aria-pressed="${ui.deck==='retry'}">${icon('refresh',17)}<span>${h(t('retryDeck'))}</span></button><p class="small"><b id="retryTotal">${q.total}</b> ${h(t('retryQueued'))} · <b id="retryReady">${q.ready}</b> ${h(t('retryReady'))}</p><p class="small retryCountdown" id="retryCountdown" ${q.next?'':'hidden'}>${q.next?h(t('retryNext'))+' '+retryCountdown(q.next):''}</p></div>`;}
function armCardTimer(){
 clearTimeout(cardTimer);
 const tick=()=>{
  if(!['cards','review'].includes(route()[0])||document.hidden||!vocabulary||!ui.card)return;
  const q=cardRetryState();
  if(!ui.card.current&&q.ready){pickCard();if(ui.card.current){render(true);return;}}
  if($('retryTotal'))$('retryTotal').textContent=q.total;
  if($('retryReady'))$('retryReady').textContent=q.ready;
  if($('retryCountdown')){$('retryCountdown').hidden=!q.next;$('retryCountdown').textContent=q.next?t('retryNext')+' '+retryCountdown(q.next):'';}
  if(q.next)cardTimer=setTimeout(tick,Math.max(1,Math.min(1000,q.next-Date.now())));
 };
 tick();
}
function newCardSession(){ui.card={done:0,skipped:new Set(),current:null,revealed:false};pickCard();}
function pickCard(includeFuture=false){if(!vocabulary)return;ui.card??={done:0,skipped:new Set(),current:null,revealed:false};const pool=cardPool(vocabulary.words,words,{topic:ui.cardTopic,deck:ui.deck,skipped:ui.card.skipped,includeFuture});ui.card.current=pool[0]||null;ui.card.revealed=false;if(ui.card.current)ui.open.delete('card:'+ui.card.current.id);}
function cardsHTML(){const reviewOnly=route()[0]==='review';if(!ui.card)newCardSession();const s=ui.card,w=s.current,reverse=ui.direction!=='de',q=cardRetryState();return `<section class="screen cardScreen"><div class="screenTitle"><h1>${h(t(reviewOnly?'retryMenu':'cards'))}</h1><button class="iconButton" data-act="reverse" aria-label="${h(t('reverse'))}">${icon('refresh',19)}</button></div><details class="ruleBox"><summary>${h(t('cardOptions'))} · <span lang="de" dir="ltr">${h(topicName(ui.cardTopic))}</span></summary><div class="cardControls" style="padding:10px 0"><select class="fullSelect" id="cardTopic" aria-label="${h(t('topic'))}">${topicOptions(ui.cardTopic)}</select>${reviewOnly?'':`<select id="cardDeck" aria-label="${h(t('deck'))}">${[['due','dueDeck'],['retry','retryDeck'],['all','all'],['star','starred'],['new','new']].map(([v,k])=>`<option value="${v}" ${ui.deck===v?'selected':''}>${h(t(k))}</option>`).join('')}</select>`}<span class="small">${h(t(reverse?'translationFirst':'deFirst'))}</span></div><p class="small">${h(t('reviewHint'))}</p></details>${retryPanelHTML(q)}${w?`<div class="flashcard"><div class="row between"><span class="pill">${h(reverse?names[settings.lang]:'DEUTSCH')}</span><span class="small">${s.done} ${h(t('reviewed'))}</span></div><div class="flashContent"><h2 lang="${reverse?settings.lang:'de'}" dir="${reverse?'auto':'ltr'}">${h(reverse?w[settings.lang]:w.de)}</h2>${s.revealed?`<div class="flashAnswer"><p lang="${reverse?'de':settings.lang}" dir="auto">${h(reverse?w.de:w[settings.lang])}</p>${relationsHTML(w)}${w.verify?`<p class="verify">${h(t('verify'))}</p>`:''}${exampleHTML(w,'card')}</div>`:''}</div>${s.revealed?`<div class="ratingButtons">${[['again','again'],['hard','hard'],['good','good']].map(([rating,cls])=>`<button class="${cls}" data-act="rate" data-rating="${rating}">${h(t(rating))}</button>`).join('')}</div>`:`<button class="primary wide" data-act="reveal">${h(t('reveal'))}</button>`}</div><div class="cardFoot"><button class="textButton" data-act="skip">${h(t('skip'))}</button><button class="textButton" data-act="new-cards">${h(t('restart'))}</button></div>`:`<div class="empty"><span class="emptyIcon" aria-hidden="true">✳</span><h2>${h(t(q.waiting?'retryWaiting':ui.deck==='retry'?'retryEmpty':'sessionDone'))}</h2><p class="small">${h(t(q.waiting?'retryWaitingHint':ui.deck==='retry'?'retryEmptyHint':ui.deck==='star'?'noStar':'emptyCards'))}</p>${q.waiting?`<button class="primary wide" data-act="retry-now">${h(t('retryNow'))}</button>`:''}<button class="primary" data-act="new-cards">${h(t('restart'))}</button><button class="secondary" data-go="words">${h(t('words'))}</button></div>`}</section>`;}
const grammarLevels=()=>[...new Set(catalog.grammarTopics.map(topic=>topic.level))];
function grammarHTML(){return `<section class="screen"><div><p class="eyebrow">GRAMMATIK ÜBUNGEN</p><h1>${h(t('chooseLevel'))}</h1><p class="subtitle">${catalog.grammarCount} ${h(t('questions'))} · ${h(t('grammarNote'))}</p></div><div class="levelCards">${grammarLevels().map(level=>{const n=catalog.grammarTopics.filter(x=>x.level===level).length;return `<button class="levelCard" data-go="grammar/topics/${level}"><strong>${level}</strong><span class="small">${n} ${h(t('topicsLabel'))}</span><span>${icon('arrow',20)}</span></button>`;}).join('')}</div><button class="actionRow" data-act="grammar-mixed"><span>${icon('refresh')}<span>${h(t('mixed'))}<br><span class="small">10 ${h(t('questions'))} · B1 + B2</span></span></span>${icon('arrow',19)}</button><button class="actionRow" data-act="grammar-errors"><span>${icon('grammar')}<span>${h(t('mistakes'))}</span></span>${icon('arrow',19)}</button><p class="small" style="margin-top:auto">${h(t('grammarNote'))}</p></section>`;}
function grammarTopicsHTML(level){if(!grammarLevels().includes(level))return grammarHTML();const topics=catalog.grammarTopics.filter(x=>x.level===level),pages=Math.ceil(topics.length/4);ui.grammarPage=Math.min(ui.grammarPage,pages-1);return `<section class="screen"><div><p class="eyebrow">${level}</p><h1>${h(t('chooseGrammarTopic'))}</h1></div><div class="grammarTopicList">${topics.slice(ui.grammarPage*4,ui.grammarPage*4+4).map((topic,i)=>{const n=topic.ids.filter(id=>results[id]?.lastCorrect).length;return `<button class="grammarTopic" data-act="grammar-topic" data-id="${topic.id}"><span class="number">${String(ui.grammarPage*4+i+1).padStart(2,'0')}</span><strong lang="de" dir="ltr">${h(topic.title)}</strong><span class="small">${n}/${topic.ids.length}</span></button>`;}).join('')}</div><div class="pager"><button class="secondary" data-act="grammar-page" data-step="-1" ${ui.grammarPage===0?'disabled':''}>${h(t('previous'))}</button><span class="small">${ui.grammarPage+1} / ${pages}</span><button class="secondary" data-act="grammar-page" data-step="1" ${ui.grammarPage===pages-1?'disabled':''}>${h(t('next'))}</button></div><div class="row"><button class="secondary grow" data-act="grammar-mixed" data-level="${level}">${h(t('mixed'))}</button><button class="secondary grow" data-act="grammar-errors" data-level="${level}">${h(t('mistakes'))}</button></div></section>`;}
function startGrammar(ids,level=null){if(!ids.length){toast('noMistakes');return;}ui.gs={ids:[...ids],index:0,score:0,checked:false,answer:'',options:shuffle(questionMap.get(ids[0]).options),level};go('grammar/exercise');}
function exerciseHTML(){const s=ui.gs;if(!s)return grammarHTML();if(s.index>=s.ids.length)return `<section class="screen"><div class="empty"><div class="scoreCircle">${s.score}/${s.ids.length}</div><h1>${h(t('finished'))}</h1><p class="small">${h(t('grammarNote'))}</p><button class="primary wide" data-act="grammar-repeat">${h(t('repeat'))}</button><button class="secondary wide" data-go="grammar">${h(t('grammar'))}</button><button class="textButton" data-go="progress">${h(t('progress'))}</button></div></section>`;
 const q=questionMap.get(s.ids[s.index]);return `<section class="screen"><div class="row between"><h1 class="exerciseTitle" lang="de" dir="ltr">${h(q.topic.title)}</h1><span class="pill">${q.topic.level}</span></div><div class="row between"><span class="small">${s.index+1} / ${s.ids.length}</span><span class="small">${s.score} ${h(t('right'))}</span></div><div class="topicBar"><span style="width:${s.index/s.ids.length*100}%"></span></div><details class="ruleBox"><summary>${h(t('rule'))}</summary><p lang="de" dir="ltr">${h(q.topic.rule)}</p></details><div><p class="small" style="margin-bottom:9px">${h(t(q.options.length?'chooseAnswer':'typeAnswer'))}</p><h2 class="exercisePrompt" lang="de" dir="ltr">${h(q.prompt)}</h2></div><form id="grammarForm" class="answerOptions">${q.options.length?s.options.map(option=>`<label class="answerOption"><input type="radio" name="answer" value="${h(option)}" ${s.answer===option?'checked':''} ${s.checked?'disabled':''}><span lang="de">${h(option)}</span></label>`).join(''):`<label><span class="srOnly">${h(t('answer'))}</span><input id="typedAnswer" name="answer" lang="de" dir="ltr" type="text" value="${h(s.answer)}" autocomplete="off" autocapitalize="off" spellcheck="false" ${s.checked?'disabled':''}></label>`}${!s.checked?`<button type="submit" class="primary wide">${h(t('check'))}</button>`:''}</form>${s.checked?`<div class="feedback ${s.correct?'':'wrong'}" role="status"><strong>${h(t(s.correct?'right':'wrong'))}</strong><p class="small">${h(t('correctAnswer'))}</p><p class="solution" lang="de" dir="ltr">${h(q.answer)}</p><p lang="de" dir="ltr">${h(q.why)}</p></div><button class="primary wide exerciseFooter" data-act="grammar-next">${h(t('next'))} ${icon('arrow',16)}</button>`:''}</section>`;}
function graphHTML(){const series=chartSeries(activity,ui.chartDays,ui.chartMetric),points=series.map((d,i)=>({...d,x:32+i*304/(series.length-1)})),max=Math.max(1,...points.map(d=>d.value||0)),top=Math.ceil(max/4)*4,scale=value=>130-value/top*100;const valid=points.filter(d=>d.value!==null);let geometry='';if(ui.chartMetric==='learned'){const line=valid.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)},${scale(p.value).toFixed(1)}`).join(' ');geometry=`<path d="${line}" class="line"/>`+valid.map(p=>`<circle class="point" cx="${p.x}" cy="${scale(p.value)}" r="3.5"><title>${p.day}: ${p.value}</title></circle>`).join('');}else geometry=valid.map(p=>`<rect class="bar" x="${p.x-3}" y="${scale(p.value)}" width="6" height="${Math.max(0,130-scale(p.value))}" rx="3"><title>${p.day}: ${p.value}</title></rect>`).join('');const labels=[0,Math.floor((points.length-1)/2),points.length-1].map(i=>`<text x="${points[i].x}" y="153" text-anchor="middle">${h(formatDay(points[i].day))}</text>`).join('');return `<svg class="chart" viewBox="0 0 360 162" role="img" aria-label="${h(t(ui.chartMetric==='learned'?'learnedWords':'activity'))}"><title>${h(t(ui.chartMetric==='learned'?'learnedWords':'activity'))}</title>${[0,top/2,top].map(n=>`<path class="grid" d="M30 ${scale(n)}H345"/><text x="23" y="${scale(n)+3}" text-anchor="end">${n}</text>`).join('')}${geometry}${labels}</svg>`;}
function formatDay(day){return new Intl.DateTimeFormat(settings.lang,{day:'numeric',month:'short'}).format(new Date(day+'T12:00:00'));}
function progressHTML(){const n=learned(),percent=pct(n,catalog.uniqueWordCount),g=grammarStats(),circ=2*Math.PI*49;return `<section class="screen progressScreen"><h1>${h(t('progress'))}</h1><div class="progressHero panel"><div class="donut"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="49" fill="none" stroke="var(--line)" stroke-width="9"/><circle cx="60" cy="60" r="49" fill="none" stroke="#92b55f" stroke-width="9" stroke-linecap="round" stroke-dasharray="${circ}" stroke-dashoffset="${circ*(1-percent/100)}"/></svg><strong>${percent}%</strong></div><div class="progressNumbers"><strong>${n}<span class="muted" style="font-size:15px"> / ${catalog.uniqueWordCount}</span></strong><p class="label">${h(t('learnedWords'))}</p><p class="small">${due()} ${h(t('due'))}</p></div></div><div class="grammarStats"><div><strong>${h(t('grammar'))} · ${g.known}/${catalog.grammarCount}</strong><p class="small">${h(t('correctLast'))}</p></div><div style="text-align:end"><strong>${g.accuracy}%</strong><p class="small">${h(t('accuracy'))}</p></div></div><a href="#/verbs" class="grammarStats verbProgress"><div><strong>${h(t('verbs'))} · ${verbCourse.stats().known}/${catalog.verbFormCount||0}</strong><p class="small">${h(t('verbForms'))}</p></div><div><strong>${verbCourse.stats().accuracy}%</strong><p class="small">${h(t('accuracy'))}</p></div></a><div class="chartPanel panel"><div class="chartHeader"><select id="chartMetric" class="chartMetric" aria-label="${h(t('progress'))}"><option value="learned" ${ui.chartMetric==='learned'?'selected':''}>${h(t('learnedWords'))}</option><option value="activity" ${ui.chartMetric==='activity'?'selected':''}>${h(t('activity'))}</option></select><div class="segmented">${[7,30].map(n=>`<button data-act="chart-days" data-days="${n}" aria-pressed="${ui.chartDays===n}">${h(t(n===7?'last7':'last30'))}</button>`).join('')}</div></div>${graphHTML()}<p class="small">${h(t('historySince'))} ${h(formatDay(activity.started))}</p></div><div class="backupButtons"><button class="primary" data-act="export">${icon('download',18)}${h(t('backupAll'))}</button><button class="iconButton" data-act="import" aria-label="${h(t('importAll'))}">${icon('upload')}</button></div></section>`;}
function settingsHTML(){const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone;return `<section class="screen"><h1>${h(t('settings'))}</h1><div class="settingsBlock"><div><h2>${h(t('language'))}</h2><p class="small">${h(t('languageHint'))}</p></div><select id="settingsLanguage" aria-label="${h(t('language'))}">${LANGS.map(l=>`<option value="${l}" ${settings.lang===l?'selected':''}>${names[l]}</option>`).join('')}</select></div><div class="settingsBlock"><h2>${h(t('appearance'))}</h2><div class="themeOptions">${['light','dark','system'].map(theme=>`<button class="themeOption" data-act="set-theme" data-theme="${theme}" aria-pressed="${settings.theme===theme}">${icon(theme==='light'?'sun':theme==='dark'?'moon':'settings',19)}<span>${h(t(theme))}</span></button>`).join('')}</div></div><div class="settingsBlock panel"><div class="row between"><strong style="font-size:14px">${h(t(installed?'installed':'install'))}</strong>${!installed?`<button class="iconButton" data-act="install" aria-label="${h(t('install'))}">${icon('download',18)}</button>`:icon('check',18)}</div><p class="small">${h(installed?offlineLabel():t('installHint'))}</p><button class="${registration?.waiting?'primary':'secondary'} wide" data-act="check-update" ${['checking','downloading'].includes(updateState)?'disabled':''}>${h(t(registration?.waiting?'updateNow':updateState==='checking'?'checkingUpdates':updateState==='downloading'?'updateDownloading':'checkUpdates'))}</button><p class="small" role="status">${h(updateError?t('updateFailed'):updateState==='current'?t('upToDate'):'')}</p></div><div class="settingsBlock"><div class="backupButtons"><button class="secondary grow" data-act="export">${h(t('backupAll'))}</button><button class="iconButton" data-act="import" aria-label="${h(t('importAll'))}">${icon('upload')}</button></div><p class="small">${h(t('savedLocal'))}</p><button class="textButton danger" data-act="reset">${h(t('resetAll'))}</button></div><div class="panel"><p class="small">${h(t('loadedContent'))}</p><strong>${catalog.wordCount} ${h(t('entries'))}</strong><p class="small">${catalog.uniqueWordCount} ${h(t('unique'))} · ${catalog.grammarCount} ${h(t('questions'))}</p></div><div class="settingFooter"><span>Wortgarten · ${APP_VERSION}</span><span>${h(offlineLabel())}</span></div></section>`;}
async function render(keepScroll=false){clearTimeout(cardTimer);closeReadingWord();const token=++routeToken,scroll=$('view').scrollTop,p=route();if(['cards','review'].includes(p[0])&&cardRoute!==p[0]){cardRoute=p[0];ui.deck=cardRoute==='review'?'retry':'due';ui.card=null;if(cardRoute==='review')ui.cardTopic='all';}document.documentElement.lang=settings.lang;document.documentElement.dir=['ar','fa'].includes(settings.lang)?'rtl':'ltr';applyTheme();header();try{
 if(p[0]==='verbs'){if(!verbCourse.data)$('view').innerHTML=loading();await verbCourse.load();}
 if(p[0]==='reading'){if(!reading)$('view').innerHTML=loading();await loadReading();}
 if((p[0]==='words'&&p.length>1)||p[0]==='cards'||p[0]==='review'){if(!vocabulary)$('view').innerHTML=loading();await loadVocabulary();}
 if(p[0]==='grammar'&&p[1]==='exercise'){if(!grammar)$('view').innerHTML=loading();await loadGrammar();}
 if(token!==routeToken)return;
 let html;if(!p.length)html=homeHTML();else if(p[0]==='words')html=p[1]?wordsHTML(p[1]):topicsHTML();else if(p[0]==='cards'||p[0]==='review')html=cardsHTML();else if(p[0]==='grammar')html=p[1]==='topics'?grammarTopicsHTML(p[2]):p[1]==='exercise'?exerciseHTML():grammarHTML();else if(p[0]==='reading')html=p[1]?readingTextHTML(p[1]):readingListHTML();else if(p[0]==='verbs')html=verbCourse.html(p[1]);else if(p[0]==='progress')html=progressHTML();else if(p[0]==='settings')html=settingsHTML();else html=homeHTML();
 $('view').innerHTML=html;if(p[0]==='words'&&p.length>1)renderWordList();$('view').scrollTop=keepScroll?scroll:0;if(!keepScroll)$('view').focus({preventScroll:true});document.title='Wortgarten · '+t(p[0]==='review'?'retryMenu':p[0]||'home');if(['cards','review'].includes(p[0]))armCardTimer();
 }catch{if(token===routeToken)$('view').innerHTML=`<section class="screen"><div class="empty"><h2>${h(t('loadError'))}</h2><button class="primary" data-act="retry">${h(t('retry'))}</button></div></section>`;}}
function changeLanguage(lang){if(!LANGS.includes(lang))return;settings.lang=lang;write(STORE.settings,settings);write(STORE.words,wordPayload());write(STORE.grammar,grammarPayload());render(true);}
function setTheme(theme){settings.theme=theme;write(STORE.settings,settings);applyTheme();render(true);}
function speak(w){if(!('speechSynthesis'in window)){toast('noVoice');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(w.de.split(',')[0].replace(/\([^)]*\)/g,''));u.lang='de-DE';const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('de'));if(voice)u.voice=voice;u.onerror=()=>toast('noVoice');speechSynthesis.speak(u);}
function exportAll(){const data={app:'WortgartenPWA',version:2,exportedAt:new Date().toISOString(),vocabulary:wordPayload(),grammar:grammarPayload(),verbs:verbPayload(),activity};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='wortgarten-all-'+dayKey()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function confirmReset(){$('confirmTitle').textContent=t('resetAll');$('confirmText').textContent=t('resetQuestion');$('cancelConfirm').textContent=t('cancel');$('acceptConfirm').textContent=t('delete');$('confirmDialog').showModal();}
async function handleAction(button){const a=button.dataset.act;if(button.disabled)return;try{
 if(button.dataset.go!==undefined){if(['verbs/practice','verbs/mistakes'].includes(button.dataset.go))verbCourse.clear();if(button.dataset.go==='review'){ui.deck='retry';ui.cardTopic='all';ui.card=null;}if(button.dataset.go==='grammar'||button.dataset.go.startsWith('grammar/topics/'))ui.grammarPage=0;go(button.dataset.go);return;}
 if(a?.startsWith('verb-')){await verbCourse.action(button);return;}
 if(a==='reading-word'){showReadingWord(button.dataset.text,Number(button.dataset.block),Number(button.dataset.token));return;}
 if(a==='reading-close'){closeReadingWord();return;}
 if(a==='reading-list-page'){ui.readingListPage=Math.max(0,ui.readingListPage+Number(button.dataset.step));render();return;}
 if(a==='reading-page'){const id=button.dataset.text;ui.readingPositions[id]=Math.max(0,(ui.readingPositions[id]||0)+Number(button.dataset.step));render();return;}
 if(a==='reading-speak'){const s=ui.readingWord;if(s){const gloss=readingLookup(reading,s.text,s.block,s.token);if(gloss)speak({de:gloss.surface});}return;}
 if(a==='reading-star'){const selected=ui.readingWord;if(!selected)return;const gloss=readingLookup(reading,selected.text,selected.block,selected.token);if(!gloss?.wordId)return;button.disabled=true;await loadVocabulary();const word=wordMap.get(gloss.wordId);if(word){saveWord(word,{star:!status(word).star});if(ui.readingWord===selected)$('readingWordContent').innerHTML=readingGlossHTML(gloss);}return;}
 if(a==='back'){go(backPath(route()));return;}
 if(a==='theme'){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');return;}
 if(a==='set-theme'){setTheme(button.dataset.theme);return;}
 if(a==='language'){changeLanguage(button.dataset.lang);return;}
 if(a==='retry'){render();return;}
 if(a==='more'){ui.limit+=24;renderWordList();return;}
 if(a==='star'||a==='learn'){const w=wordMap.get(button.dataset.id),s=status(w);saveWord(w,a==='star'?{star:!s.star}:{known:!s.known,level:s.known?0:1,due:s.known?0:Date.now()+86400000});renderWordList();return;}
 if(a==='speak'){speak(wordMap.get(button.dataset.id));return;}
 if(a==='cards-topic'){await loadVocabulary();ui.cardTopic=button.dataset.topic;newCardSession();go('cards');return;}
 if(a==='reverse'){ui.direction=ui.direction==='de'?'translation':'de';if(ui.card)ui.card.revealed=false;render();return;}
 if(a==='reveal'){if(ui.card?.current){ui.card.revealed=true;render(true);}return;}
 if(a==='retry-deck'){ui.deck='retry';newCardSession();render();return;}
 if(a==='retry-now'){ui.deck='retry';pickCard(true);render();return;}
 if(a==='new-cards'){newCardSession();render();return;}
 if(a==='skip'){if(ui.card?.current){ui.card.skipped.add(keyOf(ui.card.current));pickCard();render();}return;}
 if(a==='rate'){if(!ui.card?.current||!ui.card.revealed)return;const w=ui.card.current;words[keyOf(w)]=schedule(status(w),button.dataset.rating);write(STORE.words,wordPayload());record('review');ui.card.done++;if(button.dataset.rating==='good')ui.card.skipped.add(keyOf(w));else ui.card.skipped.delete(keyOf(w));pickCard();render();return;}
 if(a==='topic-page'){ui.topicPage+=Number(button.dataset.step);render();return;}
 if(a==='grammar-page'){ui.grammarPage+=Number(button.dataset.step);render();return;}
 if(a==='grammar-topic'||a==='grammar-mixed'||a==='grammar-errors'){button.disabled=true;await loadGrammar();const level=button.dataset.level||null;let ids;if(a==='grammar-topic'){const topic=grammar.find(x=>x.id===button.dataset.id);ids=topic.questions.map(q=>q.id);startGrammar(ids,topic.level);}else{ids=[...questionMap.values()].filter(q=>(!level||q.topic.level===level)&&(a!=='grammar-errors'||results[q.id]&&!results[q.id].lastCorrect)).map(q=>q.id);ids=shuffle(ids);startGrammar(a==='grammar-mixed'?ids.slice(0,10):ids,level);}button.disabled=false;return;}
 if(a==='grammar-next'){const s=ui.gs;if(!s?.checked)return;s.index++;s.checked=false;s.answer='';s.options=s.index<s.ids.length?shuffle(questionMap.get(s.ids[s.index]).options):[];render();return;}
 if(a==='grammar-repeat'){const s=ui.gs;if(s){startGrammar(s.ids,s.level);render();}return;}
 if(a==='chart-days'){ui.chartDays=Number(button.dataset.days);render(true);return;}
 if(a==='export'){exportAll();return;}
 if(a==='import'){$('importFile').click();return;}
 if(a==='reset'){confirmReset();return;}
 if(a==='install'){if(installPrompt){const prompt=installPrompt;installPrompt=null;await prompt.prompt();await prompt.userChoice;render(true);}else toast('installLater');return;}
 if(a==='check-update'){if(registration?.waiting){updateRequested=true;registration.waiting.postMessage({type:'SKIP_WAITING'});}else await checkForUpdates();return;}
 if(a==='update'&&registration?.waiting){updateRequested=true;registration.waiting.postMessage({type:'SKIP_WAITING'});return;}
 }catch{button.disabled=false;toast('loadError');}}
document.addEventListener('click',event=>{const button=event.target.closest('button[data-act],button[data-go]');if(button)handleAction(button);});
document.addEventListener('change',event=>{const {id,value}=event.target;if(verbCourse.change(event.target))return;if(id==='readingTopic'||id==='readingLevel'){if(id==='readingTopic')ui.readingTopic=value;else ui.readingLevel=value;ui.readingListPage=0;render();}else if(id==='quickLanguage'||id==='settingsLanguage')changeLanguage(value);else if(id==='wordFilter'){ui.filter=value;ui.limit=24;renderWordList();}else if(id==='wordTopic')go('words/'+value);else if(id==='cardTopic'||id==='cardDeck'){if(id==='cardTopic')ui.cardTopic=value;else ui.deck=value;newCardSession();render();}else if(id==='chartMetric'){ui.chartMetric=value;render(true);}else if(event.target.name==='answer'&&ui.gs)ui.gs.answer=value;});
document.addEventListener('input',event=>{if(verbCourse.input(event.target))return;if(event.target.id==='search'){ui.query=event.target.value;ui.limit=24;renderWordList();}if(event.target.id==='typedAnswer'&&ui.gs)ui.gs.answer=event.target.value;});
$('view').addEventListener('toggle',event=>{const d=event.target;if(!d.matches('details[data-example]'))return;const id=d.dataset.scope+':'+d.dataset.example;if(d.open){ui.open.add(id);if(!d.querySelector('.exampleBody'))d.insertAdjacentHTML('beforeend',exampleBody(wordMap.get(d.dataset.example)));}else ui.open.delete(id);},true);
document.addEventListener('submit',event=>{if(event.target.id==='verbForm'){event.preventDefault();verbCourse.submit();return;}if(event.target.id!=='grammarForm')return;event.preventDefault();const s=ui.gs;if(!s||s.checked)return;if(!s.answer.trim()){toast('needAnswer');return;}const q=questionMap.get(s.ids[s.index]);s.correct=evaluate(q,s.answer);s.checked=true;if(s.correct)s.score++;results[q.id]=grammarResult(results[q.id],s.correct);write(STORE.grammar,grammarPayload());record('grammar');render(true);});
$('cancelConfirm').onclick=()=>$('confirmDialog').close();$('acceptConfirm').onclick=()=>{words={};results={};verbResults={};verbCourse.clear();write(STORE.verbs,verbPayload());activity={version:1,started:dayKey(),days:{}};write(STORE.words,wordPayload());write(STORE.grammar,grammarPayload());record();ui.card=null;ui.gs=null;$('confirmDialog').close();render();};
$('importFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('large');const parsed=parseBackup(JSON.parse(await file.text()),keys,questionIds,catalog.uniqueWordCount,verbIds);if(parsed.verbs)verbResults=mergeLatest(verbResults,parsed.verbs);if(parsed.words)words=mergeLatest(words,parsed.words);if(parsed.grammar)results=mergeLatest(results,parsed.grammar);verbCourse.clear();write(STORE.verbs,verbPayload());if(parsed.activity)activity={version:1,started:[activity.started,parsed.activity.started].sort()[0],days:mergeLatest(activity.days,parsed.activity.days)};write(STORE.words,wordPayload());write(STORE.grammar,grammarPayload());record();ui.card=null;ui.gs=null;render(true);toast('imported');}catch{toast('invalid');}finally{event.target.value='';}};
$('readingDialog').addEventListener('close',()=>{ui.readingWord=null;});
$('readingDialog').addEventListener('click',event=>{if(event.target===$('readingDialog'))closeReadingWord();});
window.addEventListener('hashchange',()=>render());
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(settings.theme==='system'){applyTheme();render(true);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(route()[0]==='settings')render(true);});
window.addEventListener('appinstalled',()=>{installPrompt=null;render(true);});
window.addEventListener('storage',event=>{if(!catalog||![STORE.words,STORE.grammar,STORE.verbs,STORE.settings,STORE.activity].includes(event.key))return;try{const data=event.newValue?JSON.parse(event.newValue):null;if(event.key===STORE.words){words=data?parseWords(data,keys):{};ui.card=null;}else if(event.key===STORE.grammar){results=data?parseGrammar(data,questionIds):{};}else if(event.key===STORE.verbs){verbResults=data?parseVerbs(data,verbIds):{};verbCourse.clear();}else if(event.key===STORE.settings&&data){if(LANGS.includes(data.lang))settings.lang=data.lang;if(['light','dark','system'].includes(data.theme))settings.theme=data.theme;}else if(event.key===STORE.activity&&data)activity=parseActivity(data,catalog.uniqueWordCount);render(true);}catch{toast('invalid');}});
document.addEventListener('visibilitychange',()=>{if(document.hidden||!catalog)return;if(['cards','review'].includes(route()[0])&&ui.card&&!ui.card.current)pickCard();if(route()[0]!=='words'&&route()[1]!=='exercise')render(true);});
function refreshOfflineView(){if(!route().length||route()[0]==='settings')render(true);}
const watchedWorkers=new WeakSet();
function watchWorker(worker){
 if(!worker||watchedWorkers.has(worker))return;watchedWorkers.add(worker);
 const changed=()=>{
  if(worker.state==='installed'){
   updateState='idle';updateError=false;
   if(navigator.serviceWorker.controller)toast('updateReady');
   setTimeout(refreshOfflineView,0);
  }
  if(worker.state==='redundant'){
   if(!offlineReady&&!registration?.active)offlineFailed=true;
   updateState='idle';updateError=true;refreshOfflineView();
  }
 };
 worker.addEventListener('statechange',changed);
 if(['installed','redundant'].includes(worker.state))changed();
}
async function checkForUpdates(){
 if(updateState==='checking'||updateState==='downloading')return;
 if(!registration){toast('offlineUnavailable');return;}
 updateState='checking';updateError=false;refreshOfflineView();
 try{
  await registration.update();
  if(registration.waiting){updateState='idle';toast('updateReady');}
  else if(registration.installing){updateState='downloading';watchWorker(registration.installing);}
  else if(updateError){updateState='idle';toast('updateFailed');}
  else{updateState='current';toast('upToDate');}
 }catch{updateState='idle';updateError=true;toast('updateFailed');}
 refreshOfflineView();
}
async function setupOffline(){
 if(!('serviceWorker'in navigator)||!window.isSecureContext){offlineFailed=true;refreshOfflineView();return;}
 try{
  registration=await navigator.serviceWorker.register(new URL('./sw.js',import.meta.url),{scope:'./',updateViaCache:'none'});
  if(registration.waiting)toast('updateReady');
  watchWorker(registration.installing);
  registration.addEventListener('updatefound',()=>{
   if(navigator.serviceWorker.controller)updateState='downloading';
   watchWorker(registration.installing);refreshOfflineView();
  });
  await navigator.serviceWorker.ready;offlineReady=true;offlineFailed=false;refreshOfflineView();
 }catch{offlineFailed=true;refreshOfflineView();}
}
let reloading=false,updateRequested=false;navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(updateRequested&&registration?.active&&navigator.serviceWorker.controller&&!reloading){reloading=true;location.reload();}});
async function boot(){try{catalog=await fetchJSON('./content/catalog.json');keys=new Set(catalog.keys);verbIds=verbQuestionIds(catalog);const savedVerbs=read(STORE.verbs);if(savedVerbs){try{verbResults=parseVerbs(savedVerbs,verbIds);}catch{toast('invalid');}}questionIds=new Set(catalog.grammarTopics.flatMap(t=>t.ids));const old=read(STORE.words),oldGrammar=read(STORE.grammar),prefs=read(STORE.settings);if(old){try{words=parseWords(old,keys);if(LANGS.includes(old.lang))settings.lang=old.lang;}catch{toast('invalid');}}if(oldGrammar){try{results=parseGrammar(oldGrammar,questionIds);}catch{toast('invalid');}}if(prefs){if(LANGS.includes(prefs.lang))settings.lang=prefs.lang;if(['light','dark','system'].includes(prefs.theme))settings.theme=prefs.theme;}const history=read(STORE.activity);try{activity=history?parseActivity(history,catalog.uniqueWordCount):{version:1,started:dayKey(),days:{}};}catch{activity={version:1,started:dayKey(),days:{}};toast('invalid');}record();await render();setupOffline();}catch{$('view').innerHTML=`<div class="loading"><h1>Wortgarten</h1><p>Could not open the app. Connect to the internet and reload.</p><button class="primary" onclick="location.reload()">Try again</button></div>`;}}
boot();
